.fsx-framework{--navy: #26275B; --navy-deep: #1D1E4A; --blue: #4E98D8; --blue-ink: #2F78BA; --teal: #7CD2D3; --mid: #528FC0; --royal: #2E4DA5; --ink: #221C1B; --body: #3A3650; --muted: #6A6880; --bg: #F8F7F7; --white: #FFFFFF; --line: #E3E2EA; --star: #F4B400; --ph: #FFE45C; --grad: linear-gradient(90deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --grad-diag: linear-gradient(120deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --font: "Poppins", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --font-ui: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --content: 1240px; --pad-x: 24px; --shadow-card: 0 18px 40px -18px rgba(38, 39, 91, .28); --shadow-btn: 0 14px 30px -12px rgba(46, 77, 165, .55); --navy: #250762; --navy-deep: #1A0446; --blue: #3299D5; --blue-ink: #1F78B4; --ink: #1C1B22; --body: #2F2E36; --muted: #6B6A72; --tint: #EEF0F9; --aqua: #72CCD8; --royal: #174FA2; --grey: #D9D8D7; --teal: #72CCD8; --mid: #3299D5; --grad: linear-gradient(90deg, #72CCD8 0%, #174FA2 100%); --grad-diag: linear-gradient(120deg, #72CCD8 0%, #174FA2 100%); --grad-text: linear-gradient(90deg, #72CCD8 0%, #3299D5 45%, #174FA2 100%); --grad-primary: linear-gradient(135deg, #2B0A80 0%, #250762 55%, #200556 100%); --grad-icon: linear-gradient(135deg, #3299D5 0%, #250762 100%); --shadow-btn: 0 14px 30px -12px rgba(37, 7, 98, .55); font-family:Poppins, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;font-size:18px;line-height:28.8px;color:rgb(28, 27, 34); display:block;} .fsx-framework *, .fsx-framework *::before, .fsx-framework *::after{box-sizing:border-box;}
.fsx-framework button{background:none;border:0;padding:0;margin:0;font:inherit;color:inherit;border-radius:0;text-transform:none;letter-spacing:inherit;box-shadow:none;cursor:pointer;}
.fsx-framework button:hover, .fsx-framework button:focus{background:none;color:inherit;}
.fsx-framework a{color:inherit;text-decoration:none;background:none;} .fsx-framework a:hover{color:inherit;}
.fsx-framework h1, .fsx-framework h2, .fsx-framework h3, .fsx-framework h4, .fsx-framework p, .fsx-framework ul, .fsx-framework ol, .fsx-framework figure{margin:0;padding:0;} .fsx-framework ul, .fsx-framework ol{list-style:none;}
.fsx-framework img, .fsx-framework svg{display:block;max-width:100%;height:auto;}
.fsx-framework { --navy: #26275B; --navy-deep: #1D1E4A; --blue: #4E98D8; --blue-ink: #2F78BA; --teal: #7CD2D3; --mid: #528FC0; --royal: #2E4DA5; --ink: #221C1B; --body: #3A3650; --muted: #6A6880; --bg: #F8F7F7; --white: #FFFFFF; --line: #E3E2EA; --star: #F4B400; --ph: #FFE45C; --grad: linear-gradient(90deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --grad-diag: linear-gradient(120deg, #7CD2D3 0%, #528FC0 50%, #2E4DA5 100%); --font: "Poppins", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --font-ui: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif; --content: 1240px; --pad-x: 24px; --shadow-card: 0 18px 40px -18px rgba(38, 39, 91, .28); --shadow-btn: 0 14px 30px -12px rgba(46, 77, 165, .55); }
.fsx-framework * { box-sizing: border-box; }
.fsx-framework { scroll-behavior: smooth; text-size-adjust: 100%; }
.fsx-framework { margin: 0px; font-family: var(--font); font-size: 18px; line-height: 1.6; color: var(--ink); background: var(--bg); -webkit-font-smoothing: antialiased; }
.fsx-framework img, .fsx-framework svg { display: block; max-width: 100%; }
.fsx-framework img { height: auto; }
.fsx-framework h2, .fsx-framework h3 { margin: 0px; font-family: var(--font); color: var(--navy); line-height: 1.1; letter-spacing: -0.015em; }
.fsx-framework p { margin: 0px 0px 1em; }
.fsx-framework p:last-child { margin-bottom: 0px; }
.fsx-framework ul { margin: 0px; padding: 0px; list-style: none; }
.fsx-framework a { color: inherit; }
.fsx-framework button { font: inherit; color: inherit; }
.fsx-framework .on-dark :focus-visible { outline-color: var(--white); }
.fsx-framework .icon { width: 24px; height: 24px; flex: 0 0 auto; }
.fsx-framework .fsx-con { width: 100%; max-width: calc(var(--content) + var(--pad-x) * 2); margin-inline: auto; padding-inline: var(--pad-x); }
.fsx-framework .eyebrow { display: block; margin-bottom: 14px; font-weight: 600; font-size: 17px; color: var(--blue-ink); letter-spacing: 0px; }
.fsx-framework .h2 { font-weight: 700; font-size: clamp(34px, 3.9vw, 56px); line-height: 1.08; }
.fsx-framework .btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; padding: 14px 28px; border: 0px; border-radius: 10px; cursor: pointer; font-family: var(--font); font-weight: 500; font-size: 20px; line-height: 1.2; text-decoration: none; text-align: center; color: var(--white); background-image: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: ; background-size: 140% 100%; background-position: 0% 0px; box-shadow: var(--shadow-btn); text-shadow: rgba(20, 30, 80, 0.35) 0px 1px 2px; transition: background-position 0.35s, transform 0.2s, box-shadow 0.2s; }
.fsx-framework .btn:hover { background-position: 100% 0px; transform: translateY(-2px); box-shadow: rgba(46, 77, 165, 0.65) 0px 18px 34px -12px; }
.fsx-framework .btn--lg { padding: 18px 40px; font-size: clamp(24px, 2.6vw, 38px); border-radius: 14px; }
.fsx-framework .cta-overlap { position: relative; z-index: 3; display: flex; justify-content: center; margin-top: -46px; margin-bottom: -46px; padding-inline: var(--pad-x); }
.fsx-framework .gcard { --bw: 8px; --r: 40px; padding: var(--bw); border-radius: var(--r); background: var(--grad-diag); box-shadow: var(--shadow-card); }
.fsx-framework .gcard__in { height: 100%; background: var(--white); border-radius: calc(var(--r) - var(--bw)); }
.fsx-framework .framework { position: relative; padding-inline: 0px; }
.fsx-framework .fw-block { position: relative; overflow: hidden; color: var(--white); border-radius: clamp(40px, 9vw, 130px); padding: clamp(56px, 6vw, 72px) 0px clamp(96px, 9vw, 140px); background: radial-gradient(640px 520px at 6% 82%, rgba(91, 186, 232, .9), rgba(78, 152, 216, .35) 45%, transparent 72%), var(--navy); }
.fsx-framework .fw-head { max-width: 760px; margin: 0px auto 64px; text-align: center; }
.fsx-framework .fw-head .eyebrow { color: var(--blue); }
.fsx-framework .fw-head h2 { color: var(--white); margin-bottom: 18px; }
.fsx-framework .fw-head p { font-size: clamp(17px, 1.6vw, 22px); line-height: 1.4; color: rgba(255, 255, 255, 0.92); }
.fsx-framework .fw-head .identity { margin-top: 18px; font-style: italic; font-size: 17px; color: var(--teal); }
.fsx-framework .fw-grid { display: grid; grid-template-columns: minmax(0px, 1fr) 500px; gap: clamp(32px, 5vw, 80px); align-items: center; }
.fsx-framework .wheel { position: relative; width: 100%; max-width: 540px; margin-inline: auto; }
.fsx-framework .wheel img { width: 100%; border-radius: 50%; box-shadow: rgba(0, 0, 0, 0.45) 0px 30px 60px -20px; }
.fsx-framework .wheel svg { position: absolute; inset: 0px; width: 100%; height: 100%; }
.fsx-framework .wz { cursor: pointer; fill: transparent; outline: none; }
.fsx-framework .wz:focus-visible { stroke: var(--white); stroke-width: 10; }
.fsx-framework .wdim { fill: rgba(29, 30, 74, 0.4); pointer-events: none; transition: d 0.3s; }
.fsx-framework .wring { fill: none; stroke: var(--white); stroke-width: 9; pointer-events: none; filter: drop-shadow(rgba(124, 210, 211, 0.95) 0px 0px 14px); }
.fsx-framework .pills { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 28px; }
.fsx-framework .pill { padding: 10px 18px; border-radius: 999px; border: 1.5px solid rgba(255, 255, 255, 0.35); background: rgba(255, 255, 255, 0.06); color: var(--white); font-size: 15.5px; cursor: pointer; transition: 0.2s; }
.fsx-framework .pill b { font-weight: 700; }
.fsx-framework .pill:hover { border-color: var(--teal); }
.fsx-framework .pill[aria-selected="true"] { background: var(--white); color: var(--navy); border-color: var(--white); }
.fsx-framework .fw-card { --bw: 16px; --r: 56px; color: var(--ink); }
.fsx-framework .fw-card .gcard__in { padding: 40px 38px 44px; min-height: 600px; }
.fsx-framework .fw-content { transition: opacity 0.2s; }
.fsx-framework .fw-content.is-fading { opacity: 0; }
.fsx-framework .fw-card h3 { font-weight: 700; font-size: clamp(26px, 2.4vw, 32px); margin-bottom: 16px; }
.fsx-framework .fw-desc { font-size: 16.5px; color: var(--body); margin-bottom: 20px; }
.fsx-framework .inc-label { font-weight: 600; font-size: 14.5px; color: var(--muted); margin-bottom: 8px; }
.fsx-framework .checks li { display: flex; gap: 10px; padding: 5px 0px; font-size: 16px; }
.fsx-framework .checks .icon { width: 19px; height: 19px; margin-top: 3px; color: var(--blue-ink); }
.fsx-framework .quizbox { margin-top: 22px; padding: 14px 16px; border-radius: 12px; background: rgb(244, 243, 247); font-size: 15.5px; }
.fsx-framework .quizbox b { font-weight: 600; color: var(--navy); }
.fsx-framework .quizbox a, .fsx-framework .svc-link { color: var(--blue-ink); font-weight: 500; text-underline-offset: 3px; }
.fsx-framework .svc-link { display: inline-block; margin-top: 22px; font-size: 16px; }
@media (max-width: 1024px) { .fsx-framework .fw-grid { grid-template-columns: 1fr; } }
@media (max-width: 1024px) { .fsx-framework .fw-card { max-width: 620px; width: 100%; margin-inline: auto; } }
@media (max-width: 1024px) { .fsx-framework .fw-card .gcard__in { min-height: 0px; } }
@media (max-width: 767px) { .fsx-framework { --pad-x: 16px; } }
@media (max-width: 767px) { .fsx-framework { font-size: 16.5px; } }
@media (max-width: 767px) { .fsx-framework .fw-block { border-radius: 36px; } }
@media (max-width: 767px) { .fsx-framework .fw-card { --bw: 10px; --r: 40px; } }
@media (max-width: 767px) { .fsx-framework .fw-card .gcard__in { padding: 28px 22px 30px; } }
@media (max-width: 767px) { .fsx-framework .cta-overlap .btn { width: 100%; } }
@media (prefers-reduced-motion: reduce) { .fsx-framework { scroll-behavior: auto; } }
@media (prefers-reduced-motion: reduce) { .fsx-framework * { transition-duration: 0.01ms !important; animation: auto ease 0s 1 normal none running none !important; } }
