/* 4. Framework wheel */
  const PILLARS = [
    { name: 'Brand', icon: 'i-web', outcome: 'Build a brand people trust on sight.', desc: 'Your brand is the foundation everything else stands on. We define who you are, what makes you different, and how you show up, then make sure every touchpoint matches.', inc: ['Brand strategy and messaging', 'Logo and visual identity', 'Website design and development', 'Brand video'], quiz: 'How strong is your brand foundation?', link: 'Explore brand and web services' },
    { name: 'Thought', icon: 'i-search', outcome: 'Get found wherever customers are looking.', desc: 'When someone needs what you sell, your name should be the first one they see on Google, in AI search, on the map, and in their feed.', inc: ['SEO and AI search visibility', 'Local and map pack rankings', 'Paid advertising', 'Social media', 'Community and local partnerships'], quiz: 'Are customers finding you first?', link: 'Explore visibility services' },
    { name: 'Choice', icon: 'i-magnet', outcome: 'Turn attention into booked business.', desc: 'Getting seen is only half of it. We build the offers, lead magnets and follow-up that turn a visitor into a lead and a lead into a customer.', inc: ['Lead generation and lead magnets', 'Conversion-focused advertising', 'Marketing automation', 'CRM setup'], quiz: 'Is your marketing converting?', link: 'Explore lead generation services' },
    { name: 'Referral', icon: 'i-star', outcome: 'Make your customers your best marketing channel.', desc: 'Happy customers are the most trusted ad you\'ll ever run. We build the review, referral and loyalty systems that keep them coming back and bringing friends.', inc: ['Review generation', 'Referral programs', 'Loyalty programs', 'Retention email and automation'], quiz: 'Are your customers selling for you?', link: 'Explore loyalty and referral services' }
  ];
  // Wheel geometry (image is 1100×1100, centre 550, outer radius 545, core radius 168)
  const C = 550, RO = 545, RI = 168;
  const pt = (r, a) => { const t = a * Math.PI / 180; return [(C + r * Math.sin(t)).toFixed(1), (C - r * Math.cos(t)).toFixed(1)]; };
  const sector = (a0, a1) => { const [x1, y1] = pt(RO, a0), [x2, y2] = pt(RO, a1), [x3, y3] = pt(RI, a1), [x4, y4] = pt(RI, a0); return `M${x1} ${y1}A${RO} ${RO} 0 0 1 ${x2} ${y2}L${x3} ${y3}A${RI} ${RI} 0 0 0 ${x4} ${y4}Z`; };
  const circle = r => `M${C - r} ${C}a${r} ${r} 0 1 0 ${r * 2} 0a${r} ${r} 0 1 0 ${-r * 2} 0Z`;
  const SHAPES = [circle(RI), sector(0, 118), sector(118, 240), sector(240, 360)];
  $$('.wz').forEach(z => z.setAttribute('d', SHAPES[+z.dataset.i]));
  const wdim = $('#wdim'), wring = $('#wring');
  const pills = $$('.pill'), panel = $('#fw-panel'), content = $('#fw-content');
  let locked = 0, shown = -1, timer = null, stopped = RM, ft;

  const html = p => `
    <div class="ptag-logo"><span class="plogo" role="img" aria-label="First${p.name}"><b>first</b>${p.name.toLowerCase()}</span></div>
    <h3>${p.outcome}</h3>
    <p class="fw-desc">${p.desc}</p>
    <p class="inc-label">What's included</p>
    <ul class="checks">${p.inc.map(x => `<li><svg class="icon" aria-hidden="true"><use href="#i-check"/></svg>${x}</li>`).join('')}</ul>
    <p class="quizbox"><b>${p.quiz}</b> <a href="#" data-ph-link="Framework Quiz">Find out in the quiz.</a></p>
    <a class="svc-link" href="/firstbrand/">${p.link}</a>`;

  const show = (i, instant) => {
    wdim.setAttribute('d', circle(RO) + SHAPES[i]);
    wring.setAttribute('d', SHAPES[i]);
    pills.forEach((p, k) => { p.setAttribute('aria-selected', k === i); p.tabIndex = k === i ? 0 : -1; });
    panel.setAttribute('aria-labelledby', 'tab-' + i);
    if (i === shown) return; shown = i;
    clearTimeout(ft);
    if (instant || RM) { content.innerHTML = html(PILLARS[i]); return; }
    content.classList.add('is-fading');
    ft = setTimeout(() => { content.innerHTML = html(PILLARS[i]); content.classList.remove('is-fading'); }, 200);
  };
  const stop = () => { stopped = true; clearInterval(timer); };
  const select = i => { stop(); locked = i; show(i); };
  show(0, true);

  const hover = matchMedia('(hover: hover) and (pointer: fine)');
  $$('.wz').forEach(z => {
    const i = +z.dataset.i;
    z.addEventListener('click', () => select(i));
    z.addEventListener('mouseenter', () => { if (hover.matches) { stop(); show(i); } });
  });
  $('#wheel-svg').addEventListener('mouseleave', () => hover.matches && show(locked));
  pills.forEach((p, i) => {
    p.addEventListener('click', () => select(i));
    p.addEventListener('focus', stop);
    p.addEventListener('keydown', e => {
      let n = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = (i + 1) % 4;
      if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = (i + 3) % 4;
      if (e.key === 'Home') n = 0;
      if (e.key === 'End') n = 3;
      if (n !== null) { e.preventDefault(); select(n); pills[n].focus(); }
    });
  });
  content.addEventListener('click', e => { if (e.target.closest('a')) stop(); });
  if (!RM && 'IntersectionObserver' in window) {
    new IntersectionObserver((es, ob) => es.forEach(e => {
      if (!e.isIntersecting || stopped) return;
      ob.disconnect();
      timer = setInterval(() => { if (!stopped) { locked = (locked + 1) % 4; show(locked); } }, 5000);
    }), { threshold: 0.4 }).observe($('.fw-grid'));
  }
